import {readFileSync,writeFileSync} from 'node:fs';
import {spawnSync} from 'node:child_process';
import {isDeepStrictEqual} from 'node:util';
import {sha256,publicEvidence,readEvidence} from '../../../scripts/eval/p2/artifacts.ts';
import {rescoreRun,readJudgments} from '../../../scripts/eval/p2/rescore.ts';
import {scoreEvidenceV2} from '../../../scripts/eval/p2/score-v2.ts';
const base='story/testing/runs/P2R', approvalPath=base+'/P2R-DECISIONS/20261031-d4-author-acceptance/approval.json', final=base+'/P2-ACCEPTANCE/20261031-d4-final';
const read=p=>JSON.parse(readFileSync(p,'utf8')),approval=read(approvalPath),sources=new Map();
const gitFile=p=>{const r=spawnSync('git',['show',`${approval.evidenceHead}:${p}`],{windowsHide:true,maxBuffer:32*1024*1024});if(r.status!==0)throw Error('Cannot recover original '+p);return r.stdout;};
const planned=approval.originalJudgmentFiles.map(f=>{
 const bytes=gitFile(f.path);if(sha256(bytes)!==f.sha256)throw Error('Original differs '+f.path);
 const original=JSON.parse(bytes),current=read(f.path);
 if(current.scores.length!==original.scores.length||current.approval?.evidence!==approvalPath)throw Error('Concurrent judgment change');
 for(let i=0;i<current.scores.length;i++){
  const old=original.scores[i],now=current.scores[i];
  if(now.sampleId!==old.sampleId||now.preApproval?.pass!==old.pass||now.preApproval?.note!==old.note)throw Error('Unowned original change');
  const reconstructed={...now,...now.preApproval};delete reconstructed.preApproval;delete reconstructed.correctionEvidence;delete reconstructed.authorPersonallyReviewed;
  if(!isDeepStrictEqual(reconstructed,old))throw Error('Unexpected row modification');
 }
 const folder=f.path.split('/judgments/')[0],entry=sources.get(folder)??{folder,runId:current.runId,sourceFiles:[],judgments:[]};
 entry.sourceFiles.push({path:f.path,sha256:f.sha256});
 entry.judgments.push(...current.scores.map(({metric,component,sampleId,runId,pass,status})=>({metric,component,sampleId,runId,pass,status})));
 sources.set(folder,entry);return{path:f.path,bytes};
});
// Capture approved, corrected scores without changing test-session-owned source files.
const overlays=[...sources.values()].map(x=>({...x,approvalPath,approvalSha256:sha256(readFileSync(approvalPath)),metrics:scoreEvidenceV2(readEvidence(x.folder,true),x.judgments)}));
for(const x of overlays){if(!isDeepStrictEqual(read(x.folder+'/metrics.json'),x.metrics))throw Error('Derived score mismatch');}
for(const x of planned)writeFileSync(x.path,x.bytes);
for(const x of overlays)writeFileSync(x.folder+'/metrics.json',gitFile(x.folder+'/metrics.json'));
for(const x of planned){if(sha256(readFileSync(x.path))!==sha256(x.bytes))throw Error('Restore mismatch');}
for(const x of overlays){if(!rescoreRun(x.folder).equal||readJudgments(x.folder).some(r=>r.status!=='ai_preliminary'))throw Error('Original state not reproduced');}
const json=x=>{const t=JSON.stringify(x,null,2)+'\n';publicEvidence(t);return t;};
writeFileSync(final+'/approved-score-overlays.json',json({schema:'story/p2r-approved-score-overlays@1',approvalPath,sourceFreeze:approval.sourceFreeze,originalFilesPreserved:true,originalMetricsPreserved:true,overlays}),{flag:'wx'});
approval.application='只在P2-ACCEPTANCE/20261031-d4-final/approved-score-overlays.json中叠加批准和纠错；31份原judgments及6份原metrics保持交付状态。评分仍调用冻结scoreEvidenceV2，不复制或改写raw。';
approval.notes[0]='原判保持在31份源judgments中，原始交付提交7706c4e63可恢复。所有被撤回的写入均先逐字段验证仅为本会话批准层改动。';
approval.ownershipCorrection={source:'19-P2执行方案 §1.3',rule:'judgments/ 属于测试集会话，不修改',action:'原文件按交付哈希验证后保留；批准及纠错写在执行会话负责的派生验收汇总中。'};
writeFileSync(approvalPath,json(approval));
// Refresh the approval digest in the derivative artifact after recording its application boundary.
for(const x of overlays)x.approvalSha256=sha256(readFileSync(approvalPath));
writeFileSync(final+'/approved-score-overlays.json',json({schema:'story/p2r-approved-score-overlays@1',approvalPath,sourceFreeze:approval.sourceFreeze,originalFilesPreserved:true,originalMetricsPreserved:true,overlays}));
const source=readFileSync(import.meta.filename,'utf8');writeFileSync(final+'/overlay-reproduction.json',json({scriptPath:'story/testing/exec/temp/p2r-preserve-judge-delivery.mjs',source,sourceSha256:sha256(source),note:'一次性所有权纠正过程；原文件已恢复，不重复执行。后续直接用批准叠加分数与scoreEvidenceV2重算。'}),{flag:'wx'});
console.log(JSON.stringify({preservedJudgmentFiles:planned.length,preservedMetrics:overlays.length,derivedJudgments:overlays.reduce((n,x)=>n+x.judgments.length,0)}));
